SELECT

FROM car_confim_free t
left join sys_dept sd on sd.dept_id = t.org_id
WHERE t.del_flag = '0'
 and t.id = #{id}
 and t.car_id = #{carId}
 and t.car_no = #{carNo}
 and t.car_type = #{carType}
 and t.car_vehicle = #{carVehicle}
 and t.link_name like concat('%', #{linkName}, '%')
 and t.link_phone = #{linkPhone}
 and t.org_id = #{orgId}
 and sd.dept_name like concat('%', #{orgName}, '%')
 and t.user_ids = #{userIds}
 and t.user_names = #{userNames}
 and t.amount = #{amount}
 and t.escaped_types = #{escapedTypes}
 and t.back_col1 = #{backCol1}
 and t.back_col2 = #{backCol2}
 and t.status = #{status}
 and t.sort = #{sort}
 and t.eps_id = #{epsId}
 and t.tenant_id = #{tenantId}
 and t.create_by = #{createBy}
 and find_in_set(t.id,#{exceptIds}) > 0 
 and t.car_no like concat('%', #{carNoQuery}, '%')
and t.create_time >= STR_TO_DATE(#{applyTime1},'%Y-%m-%d %H:%i:%s')
and t.create_time <= STR_TO_DATE(#{applyTime2},'%Y-%m-%d %H:%i:%s') 
order by t.create_time desc,t.id

SELECT
t.car_no,
t.car_type,
t.car_vehicle,
t.link_name,
t.link_phone,
t.org_id,
sd.dept_name org_name,
round(ifnull(sum(t.amount),0),2) amount,
round(ifnull(sum(t.aduit_amount),0),2) aduit_amount,
GROUP_CONCAT(t.except_ids SEPARATOR ', ') except_ids
FROM car_confim_free t
left join sys_dept sd on sd.dept_id = t.org_id
WHERE t.del_flag = '0'
 and t.id = #{id}
 and t.car_id = #{carId}
 and t.car_no = #{carNo}
 and t.car_type = #{carType}
 and t.car_vehicle = #{carVehicle}
 and t.link_name like concat('%', #{linkName}, '%')
 and t.link_phone = #{linkPhone}
 and t.org_id = #{orgId}
 and sd.dept_name like concat('%', #{orgName}, '%')
 and t.user_ids = #{userIds}
 and t.user_names = #{userNames}
 and t.amount = #{amount}
 and t.escaped_types = #{escapedTypes}
 and t.back_col1 = #{backCol1}
 and t.back_col2 = #{backCol2}
 and t.status = #{status}
 and t.sort = #{sort}
 and t.eps_id = #{epsId}
 and t.tenant_id = #{tenantId}
 and t.create_by = #{createBy}
 and find_in_set(t.id,#{exceptIds}) > 0 
 and t.car_no like concat('%', #{carNoQuery}, '%')
and t.create_time >= STR_TO_DATE(#{applyTime1},'%Y-%m-%d %H:%i:%s')
and t.create_time <= STR_TO_DATE(#{applyTime2},'%Y-%m-%d %H:%i:%s') 
group by  t.car_no,  t.car_type, t.car_vehicle,t.link_name, t.link_phone, t.org_id
